import 'dart:async';
import 'package:flutter/material.dart';
class PartyCountdown extends StatefulWidget{final DateTime startAt,endAt;final String style;const PartyCountdown({super.key,required this.startAt,required this.endAt,this.style='digital'});@override State<PartyCountdown>createState()=>_PartyCountdownState();}
class _PartyCountdownState extends State<PartyCountdown>{Timer? t;Duration remaining=Duration.zero;String state='LIVE';@override void initState(){super.initState();_tick();t=Timer.periodic(const Duration(seconds:1),(_)=>_tick());}@override void dispose(){t?.cancel();super.dispose();}void _tick(){final n=DateTime.now().toUtc();setState((){if(n.isBefore(widget.startAt)){state='STARTS IN';remaining=widget.startAt.difference(n);}else if(n.isBefore(widget.endAt)){state='LIVE';remaining=widget.endAt.difference(n);}else{state='ENDED';remaining=Duration.zero;}});}String f(Duration d){final s=d.inSeconds.clamp(0,99999999);final days=s~/86400,h=(s%86400)~/3600,m=(s%3600)~/60,sec=s%60;return days>0?'$days:${h.toString().padLeft(2,'0')}:${m.toString().padLeft(2,'0')}:${sec.toString().padLeft(2,'0')}':'${h.toString().padLeft(2,'0')}:${m.toString().padLeft(2,'0')}:${sec.toString().padLeft(2,'0')}';} @override Widget build(BuildContext c){final big=widget.style=='gothic'||widget.style=='cinema'||widget.style=='motor';return Column(children:[Text(state,style:Theme.of(c).textTheme.labelMedium),const SizedBox(height:4),Text(f(remaining),style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800,letterSpacing:big?2:0))]);}}
